-- 接收器
TJ.Init2(function()
    TJ.boardVers = {}
    TJ.BoardVerFrame = {}
    local sending = {}
    local sendDone = {}
    local sendingCount = {}
    local notShowSendingText = {}

    local cd
    local function CanSend()
        if IsAddOnLoaded("WeakAuras") then
            if not IsAddOnLoaded("WeakAurasOptions") then
                if not LoadAddOn("WeakAurasOptions") then
                    ns.SendSystemMessage(L["你没有启用WeakAurasOptions插件。"])
                    return
                end
            end
            return true
        else
            ns.SendSystemMessage(L["你没有安装WeakAuras插件。"])
        end
    end
    local function StartSend()
        if cd then return end
        for i = 1, 10 do
            local header = _G["WeakAurasLoadedHeaderButton" .. i]
            if header then
                local titleString = _G[header:GetName() .. "Text"]:GetText()
                if titleString:match("/") then
                    -- local tbl = { header.obj.parent.scrollframe:GetScrollChild():GetChildren() }
                    local tbl = { header:GetParent():GetChildren() }
                    for i, bt in ipairs(tbl) do
                        if bt.id and WeakAuras.IsAuraLoaded(bt.id) then
                            local ver = bt.id:match("<TuanJian>战术板接收器%s-v(%d+%.%d+)")
                            if ver then
                                if IsShiftKeyDown() then
                                    cd = true
                                    After(2, function() cd = nil end)
                                    TJ.PlaySound(2)
                                    local edit = ChatEdit_ChooseBoxForSend()
                                    edit:SetText("")
                                    ChatEdit_ActivateChat(edit)
                                    bt:Click()
                                    TJ.BoardVerFrame.WACode = edit:GetText()
                                    edit:SetText("")
                                    edit:Hide()
                                    GameTooltip:Hide()
                                    if TJ.BoardVerFrame.isOnEnter then
                                        TJ.BoardVerFrame:GetScript("OnEnter")(TJ.BoardVerFrame)
                                    end
                                    if TJ.BoardVerFrame.WACode ~= "" then
                                        -- local tbl = {}
                                        -- for _, v in ipairs(TJ.raidRosterInfo) do
                                        --     if not TJ.boardVers[v.name] and v.online then
                                        --         tinsert(tbl, v.name)
                                        --     end
                                        -- end
                                        -- if next(tbl) then
                                        -- if #tbl <= 10 then
                                        --     for _, name in ipairs(tbl) do
                                        --         SendChatMessage(TJ.BoardVerFrame.WACode, "WHISPER", nil, name)
                                        --     end
                                        -- else
                                        SendChatMessage(TJ.BoardVerFrame.WACode, "RAID")
                                        -- end
                                        -- end
                                    end
                                else
                                    ns.SendSystemMessage(L["需要按下SHIFT才能发送WA。"])
                                end
                                return
                            end
                        end
                    end
                    break
                end
            end
        end
        ns.SendSystemMessage(L["在你的WA面板里未找到战术板接收器WA字符串，你需要先点击\"安装接收器WA\"按钮。"])
    end
    local function SendWACode()
        if not CanSend() then return end
        if not IsShiftKeyDown() then return end
        if not WeakAurasOptions then
            WeakAuras.OpenOptions()
            WeakAurasOptions:Hide()
            TJ.BoardVerFrame.total = 0
            for _, _ in pairs(WeakAurasSaved.displays) do
                TJ.BoardVerFrame.total = TJ.BoardVerFrame.total + 1
            end
            TJ.OnUpdateTime(function(self)
                TJ.BoardVerFrame.loadProgressNum = WeakAurasOptions.loadProgressNum
                if TJ.BoardVerFrame.raidVerFrame.isOnEnter then
                    TJ.BoardVerFrame.raidVerFrame:GetScript("OnEnter")(TJ.BoardVerFrame.raidVerFrame)
                end
                if not WeakAurasOptions.loadProgress:IsShown() then
                    self:SetScript("OnUpdate", nil)
                    self:Hide()
                    TJ.BoardVerFrame.total = nil
                    TJ.BoardVerFrame.loadProgressNum = nil
                    if TJ.BoardVerFrame.raidVerFrame.isOnEnter then
                        TJ.BoardVerFrame.raidVerFrame:GetScript("OnEnter")(TJ.BoardVerFrame.raidVerFrame)
                    end
                    After(0, function()
                        StartSend()
                    end)
                end
            end)
        else
            StartSend()
        end
    end
    local function GetVerNum(str)
        return tonumber(str:match("v(%d+%.%d+)")) or 0
    end

    local function OnEnter(self)
        self.isOnEnter = true

        if not IsInRaid(1) then return end

        local line = 2
        GameTooltip:SetOwner(self, "ANCHOR_TOPLEFT", 0, 0)
        GameTooltip:ClearLines()
        GameTooltip:AddLine(L["团员已装接收器WA"], 0, 1, 0)
        GameTooltip:AddLine(L["相关人员需安装接收器WA，否则不会看到减伤进度条。"], 0.5, 0.5, 0.5, true)
        local text = ""
        if not WeakAurasOptions then
            text = TJ.STC_r1(L["（WA面板尚未初始化）"])
        elseif TJ.BoardVerFrame.loadProgressNum and TJ.BoardVerFrame.total then
            text = TJ.STC_y1(format(L["（WA面板正在初始化：%s/%s）"],
                TJ.BoardVerFrame.loadProgressNum, TJ.BoardVerFrame.total))
        else
            text = TJ.STC_g1(L["（WA面板已初始化，可以发送了）"])
        end
        GameTooltip:AddLine(L["SHIFT+点击：把WA字符串发送到团队频道。"] .. text, 1, 1, 1, true)
        line = line + 2
        GameTooltip:AddLine(" ")
        for i, v in ipairs(TJ.SortRaidRosterInfo()) do
            local name = v.name
            local Ver = TJ.boardVers[name]
            if not Ver then
                if v.online then
                    Ver = L["无"]
                else
                    Ver = L["未知"]
                end
                if sendDone[name] then
                    Ver = L["接收完毕，但未导入"]
                elseif sending[name] then
                    Ver = L["正在接收拍卖WA"]
                end
            elseif GetVerNum(Ver) < 2 then
                Ver = Ver .. L["（该版本已失效）"]
            end
            local role = ""
            local y
            if v.rank == 2 then
                role = role .. AddTexture("interface/groupframe/ui-group-leadericon", y)
            elseif v.rank == 1 then
                role = role .. AddTexture("interface/groupframe/ui-group-assistanticon", y)
            end
            if v.isML then
                role = role .. AddTexture("interface/groupframe/ui-group-masterlooter", y)
            end
            local c1, c2, c3 = GetClassRGB(name)
            GameTooltip:AddDoubleLine(name .. role, Ver, c1, c2, c3, 1, 1, 1)
            if Ver == L["无"] or Ver == L["未知"] or Ver:find(L["失效"]) then
                local alpha = 0.4
                if _G["GameTooltipTextLeft" .. (i + line)] then
                    _G["GameTooltipTextLeft" .. (i + line)]:SetAlpha(alpha)
                end
                if _G["GameTooltipTextRight" .. (i + line)] then
                    _G["GameTooltipTextRight" .. (i + line)]:SetAlpha(alpha)
                end
            end
        end
        GameTooltip:Show()
    end
